// Scan lib/motto-sentences.ts for articles with sentences missing ending punctuation.
// Splits the ja field on sentence boundaries (。？!), filters empty + short fragments,
// and reports any sentence whose last non-whitespace char is NOT in 。？！.
// Reports: id, sentence count, missing-punctuation sentence indices + preview.

import { readFileSync } from "node:fs";

const F = "lib/motto-sentences.ts";
const src = readFileSync(F, "utf8");

// Pull each entry's id + ja string via a tolerant regex.
// motto-sentences.ts is generated by build-motto-sentences.mjs, structure is stable:
//   { "id": "...", "ja": "...", "jaHtml": "...", "zh": "..." ... }
const entryRe =
  /\{\s*"id":\s*"([^"]+)"[\s\S]*?"ja":\s*"((?:[^"\\]|\\.)*)"/g;

const PUNCT_RE = /[。？！?!]/;
const SENT_SPLIT_RE = /(?<=[。？！?!])\s*/;

const results = [];
let m;
while ((m = entryRe.exec(src)) !== null) {
  const [, id, jaRaw] = m;
  const ja = jaRaw
    .replace(/\\"/g, '"')
    .replace(/\\n/g, "\n")
    .replace(/\\\\/g, "\\");

  // 1) Check the whole field — if it doesn't end with 。？！, that's missing final punct
  const lastChar = ja.replace(/\s+$/, "").slice(-1);
  const fieldEndsClean = PUNCT_RE.test(lastChar);

  // 2) Split into rough sentences (using punctuation + \n as separator)
  const sentences = ja
    .split(SENT_SPLIT_RE)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);

  // 3) Find sentences whose last char isn't punctuation (or sentence is too short + missing)
  const missing = [];
  for (let i = 0; i < sentences.length; i++) {
    const s = sentences[i];
    const last = s.slice(-1);
    if (!PUNCT_RE.test(last)) {
      missing.push({ idx: i, text: s, len: s.length });
    }
  }

  if (!fieldEndsClean || missing.length > 0) {
    results.push({
      id,
      sentenceCount: sentences.length,
      fieldEndsClean,
      missingCount: missing.length,
      missing,
    });
  }
}

const total = results.length;
// Sort by severity: more missing > less missing
results.sort((a, b) => b.missingCount - a.missingCount);

console.log(
  `Total articles in ${F}: ${(src.match(/"id":/g) || []).length}`
);
console.log(
  `Articles with punctuation issues: ${total}`
);
console.log("=".repeat(80));
for (const r of results) {
  console.log(
    `\n[${r.id}] sentences=${r.sentenceCount} missing=${r.missingCount} fieldEndsClean=${r.fieldEndsClean}`
  );
  for (const m of r.missing) {
    const preview = m.text.length > 60 ? m.text.slice(0, 57) + "..." : m.text;
    console.log(`  - (len ${m.len}) "${preview}"`);
  }
}

// Top 10 with most missing sentences (most urgent)
console.log("\n" + "=".repeat(80));
console.log("Top 10 by missing-punctuation sentence count:");
for (const r of results.slice(0, 10)) {
  console.log(`  ${r.id}: ${r.missingCount} missing / ${r.sentenceCount} sentences`);
}
